import{waveform,mainsFigure,energyFigure,gridFigure}from './el3-figures.js?v=20261023-physicscomplete01';
const f=(title,steps,render,note)=>({title,steps,render,note,duration:16});export const el3Films={
'el3-sources':f('Follow alternating polarity',['First cycle: positive half.','First cycle: negative half.','Second cycle: positive half.','Second cycle: negative half; repeat.'],p=>waveform({movie:true,progress:p}),'Normalised sine-wave height, not 230 V peak. Two full 50 Hz cycles (40 ms) expanded into 16 s of playback. Marker follows voltage, not an electron or current path. DC comparison remains in the experiment.'),
'el3-mains':f('Follow protective disconnection',['Normal: live and neutral carry operating current; earth does not.','Live-case fault creates a protective earth path.','Suitable protection disconnects live.'],p=>mainsFigure({movie:true,progress:p}),'Conceptual earthed metal-case appliance. No real fault current, fuse rating or trip-time calculation. Sequence reset replays an example; it does not advise repeated energising. No live-mains activity. The protective path, correct protection and insulation have distinct roles.'),
'el3-power':f('Count joules each second',['12 V and 2 A gives 24 W input.','Each second transfers 24 J.','Energy continues accumulating.','10 seconds transfers 240 J.'],p=>energyFigure({kind:'power',movie:true,progress:p}),'Constant input power. Ten model seconds expanded to 16 playback seconds. Bar is an energy account, not charge consumed or useful-output efficiency; replay resets the worked example.'),
'el3-appliances':f('Run a constant-power appliance',['60 W means 60 J each second.','The duration increases.','Total transferred energy grows.','10 seconds transfers 600 J.'],p=>energyFigure({kind:'appliances',movie:true,progress:p}),'Constant input; no temperature or motor-speed dynamics. Input includes useful and dissipated transfers. Ten model seconds expanded to 16 playback seconds; replay resets only the example.'),
'el3-grid':f('Reduce cable heating',['1000 W at 100 V needs 10 A.','1 Ω cable dissipates 100 W.','At 200 V, the same 1000 W needs 5 A.','Cable heating falls to 25 W.'],p=>gridFigure({movie:true,progress:p}),'Two separate steady sending states at the same 1000 W and 1 Ω total line resistance. Toy voltages are not actual transmission ratings. Transformer blocks show purpose; additional network/transformer losses omitted. Dots indicate energy-transfer direction, not literal charge crossing transformers. Reset compares examples, not a real switching transient.')};
